INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (7574, 'Case Study: Cách viết OKR cho Marketing Team', 'case-study-cach-viet-okr-marketing', '		<div data-elementor-type="wp-post" data-elementor-id="7574" class="elementor elementor-7574" data-elementor-post-type="post">
				<div class="elementor-element elementor-element-2b1286f e-con-full e-flex e-con e-parent" data-id="2b1286f" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
		<div class="elementor-element elementor-element-95a8097 e-con-full e-flex e-con e-parent" data-id="95a8097" data-element_type="container" data-settings="{&quot;background_background&quot;:&quot;classic&quot;,&quot;jet_parallax_layout_list&quot;:[]}">
		<div class="elementor-element elementor-element-25f3d33 e-flex e-con-boxed e-con e-parent" data-id="25f3d33" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
					<div class="e-con-inner">
